<?php namespace Tests\Unit; use App\Models\PrayerSetting; use App\Services\PrayerTimeService; use Carbon\Carbon; use PHPUnit\Framework\TestCase;
class PrayerTimeServiceTest extends TestCase { public function test_faisalabad_times_are_ordered(): void { $s=new PrayerSetting(['latitude'=>31.4504,'longitude'=>73.1350,'timezone'=>'Asia/Karachi','calculation_method'=>'Karachi','fajr_angle'=>18,'isha_angle'=>18,'asr_juristic'=>'Hanafi','asr_shadow_factor'=>2,'adjustments'=>[]]); $t=(new PrayerTimeService())->computeForDate($s,Carbon::parse('2026-06-15')); $this->assertTrue($t['fajr']<$t['dhuhr'] && $t['dhuhr']<$t['asr'] && $t['asr']<$t['maghrib'] && $t['maghrib']<$t['isha']); } }
